import {writeFile,mkdir,appendFile} from 'node:fs/promises';
const repository=process.env.GITHUB_REPOSITORY,ghToken=process.env.GITHUB_TOKEN,cfToken=process.env.CLOUDFLARE_API_TOKEN,account='71fb53fce0685a83a5b15712414cfc25';
const report={date:new Date().toISOString(),repository,mutations:[],limits:[],deployments:[],anonymousChecks:[]};
async function github(path,method='GET'){const r=await fetch('https://api.github.com/repos/'+repository+path,{method,headers:{Authorization:'Bearer '+ghToken,Accept:'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28'}});if(!r.ok)throw Error('GitHub '+method+' '+path+': HTTP '+r.status);return r.status===204?null:r.json();}
async function cf(path){const r=await fetch('https://api.cloudflare.com/client/v4/accounts/'+account+path,{headers:{Authorization:'Bearer '+cfToken},signal:AbortSignal.timeout(25000)});const value=await r.json();if(!r.ok||!value.success)return {ok:false,status:r.status};return {ok:true,data:value.result,info:value.result_info};}
// Stop only development publishers; never disable the public club's production workflow.
const workflows=(await github('/actions/workflows?per_page=100')).workflows;
for(const w of workflows.filter(w=>/\/(vista-previa-autovia|vista-previa-contacto-circuito)\.yml$/.test(w.path))){
 try{await github('/actions/workflows/'+w.id+'/disable','PUT');report.mutations.push({workflow:w.path,state:'disabled'});for(const status of ['queued','in_progress'])for(const run of (await github('/actions/workflows/'+w.id+'/runs?status='+status+'&per_page=100')).workflow_runs){try{await github('/actions/runs/'+run.id+'/cancel','POST');report.mutations.push({run:run.id,state:'cancel_requested'});}catch{report.limits.push('No se pudo cancelar la ejecución '+run.id);}}}catch(e){report.limits.push(e.message);}
}
const meta=await github('');report.github={visibility:meta.visibility,owner:meta.owner.login,codePublic:!meta.private,raulCanReadIfPublic:!meta.private};
const project=await cf('/pages/projects/octaviaap');if(!project.ok)throw Error('No se pudo leer el proyecto Pages: HTTP '+project.status);
report.production={id:project.data.canonical_deployment?.id,branch:project.data.production_branch,url:project.data.canonical_deployment?.url};
report.project={name:project.data.name,accessAppId:project.data.access_app_id||null,previewAccessAppId:project.data.deployment_configs?.preview?.access_app_id||null};
const members=await cf('/members');report.accountMembershipAudit={available:members.ok,status:members.ok?200:members.status};
if(members.ok)report.accountMembershipAudit={...report.accountMembershipAudit,albertoPresent:members.data.some(m=>m.user?.email?.toLowerCase()==='albertouceda77@gmail.com'),raulPresent:members.data.some(m=>m.user?.email?.toLowerCase()==='mozos.raul@gmail.com')};
const access=await cf('/access/apps');report.accessAudit={available:access.ok,status:access.ok?200:access.status};if(access.ok)report.accessAudit.matchingApps=access.data.filter(a=>(a.domain||'').includes('octaviaap.pages.dev')).map(a=>({id:a.id,domain:a.domain,type:a.type}));
const targets=new Set(['autovia-pr23','simulador-multiplataforma','octavia-realismo','circuito-contacto']);
for(let page=1;page<=20;page++){const result=await cf('/pages/projects/octaviaap/deployments?per_page=25&page='+page);if(!result.ok){report.limits.push('No se pudo completar la página '+page+' de despliegues');break;}if(!result.data.length)break;for(const d of result.data){const branch=d.deployment_trigger?.metadata?.branch;if(d.environment==='preview'&&targets.has(branch))report.deployments.push({id:d.id,branch,url:d.url,aliases:d.aliases||[],createdOn:d.created_on,commit:d.deployment_trigger?.metadata?.commit_hash});}if(result.data.length<25)break;}
const urls=[...new Set(['https://octaviaap.pages.dev','https://7228bc9b.octaviaap.pages.dev',...report.deployments.map(d=>d.url)])];
for(const base of urls){for(const path of ['/simulador?experience=highway','/highway.mjs','/assets/highway/octavia-mk4.glb']){try{const r=await fetch(base+path,{redirect:'manual',headers:{Range:'bytes=0-63'},signal:AbortSignal.timeout(15000)});const location=r.headers.get('location')||'';report.anonymousChecks.push({url:base+path,status:r.status,contentType:r.headers.get('content-type'),accessRedirect:/cloudflareaccess\.com|\/cdn-cgi\/access\//.test(location)});await r.body?.cancel();}catch{report.anonymousChecks.push({url:base+path,error:'No se pudo comprobar'});}}}
const after=await cf('/pages/projects/octaviaap');report.productionUnchanged=after.ok&&after.data.canonical_deployment?.id===report.production.id;
await mkdir('artifacts',{recursive:true});await writeFile('artifacts/auditoria-privacidad-autovia.json',JSON.stringify(report,null,2));
console.log('AUDITORIA_PRIVACIDAD '+JSON.stringify(report));if(process.env.GITHUB_STEP_SUMMARY)await appendFile(process.env.GITHUB_STEP_SUMMARY,'\nAuditoría de privacidad realizada. Se han detenido únicamente los publicadores de pruebas identificados. No se han borrado despliegues ni cambiado datos, miembros o producción. Revisar el informe: no se afirma protección hasta verificar acceso anónimo bloqueado.\n');
